const GENERICO = '0000000001';
const NOMBRES_CF = { [GENERICO]: 'Genérico', '4400000173': 'VICKY FOODS PRODUCTS SLU' };
const nombreCf = (c) => NOMBRES_CF[c] || (c ? `Cliente factura ${c}` : 'Sin cliente factura');

// Mensaje de la API dentro de un error de n8n: '404 - {"mensaje":"No hay datos comerciales (CLP) ..."}'.
const mensajeApi = (err) => (String(err?.message || '').match(/"(?:mensaje|message)"\s*:\s*"([^"]*)"/) || [])[1];

// Lee la salida de un nodo HTTP de la API ({ data } en texto, o { error } si no ha respondido).
// Devuelve { datos } o { error } con un mensaje para el usuario. lista = true: se espera un array.
function leerApi(r, que, lista = false) {
  if (r.error) {
    return { error: mensajeApi(r.error) || `La API de ${que} no responde o ha dado un error. Prueba de nuevo en unos segundos.` };
  }
  let d;
  try {
    d = JSON.parse(r.data);
  } catch (err) {
    return { error: `La API de ${que} ha devuelto una respuesta no válida.` };
  }
  if (lista && !Array.isArray(d)) return { error: d?.mensaje || `La API de ${que} ha dado un error.` };
  return { datos: d };
}

// Búsqueda por palabras en las descripciones, sin tildes ni mayúsculas y sin palabras vacías
// ("poker de vainilla" → POKER, VAINILLA). aciertos(texto) = cuántas palabras de la búsqueda contiene el texto.
const plano = (s) => t(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase();
const VACIAS = new Set(['DE', 'DEL', 'LA', 'EL', 'LOS', 'LAS', 'CON', 'Y', 'EN', 'AL', 'A', 'UN', 'UNA', 'PARA', 'POR']);
function buscador(busqueda) {
  const palabras = plano(busqueda).split(/[\s,.;]+/).filter((w) => w && !VACIAS.has(w));
  return { palabras, aciertos: (texto) => { const p = plano(texto); return palabras.filter((w) => p.includes(w)).length; } };
}

// Código del nodo "Normalizar" del flujo chat-ia-clientes-ayc.json (build_workflow.py lo copia en el JSON, precedido
// de comun.js). Convierte la respuesta de consultarClientes en { total, requiere_eleccion, hay_mas, resultados }.
const LIMITE = 10;
const dato = t($('Consulta').first().json.dato).toUpperCase();

if (!dato) return fallo('Falta el dato a buscar (nombre, CIF/NIF o código de cliente).');
const { datos: lista, error } = leerApi($input.first().json, 'clientes', true);
if (error) return fallo(error);

// nombreClienteCadena solo viene si el cliente es de una cadena (~4 %) y nombreClienteFactura
// casi siempre es igual al nombre: se dejan vacíos si faltan o coinciden con el nombre.
const distinto = (v, nombre) => (t(v) && t(v) !== nombre ? t(v) : '');
const clientes = lista.map((c) => ({
  codigo: t(c.codigoCliente),
  nombre: t(c.nombreCliente),
  cadena: distinto(c.nombreClienteCadena, t(c.nombreCliente)),
  nombre_factura: distinto(c.nombreClienteFactura, t(c.nombreCliente)),
  cif: t(c.cif),
  direccion: t(c.direccion),
  codigo_postal: t(c.codigoPostal),
  poblacion: t(c.poblacion),
  provincia: t(c.provincia),
}));

// Primero las coincidencias exactas de código o CIF, después por nombre.
const exacto = (c) => (c.codigo === dato || c.cif === dato ? 0 : 1);
clientes.sort((a, b) => exacto(a) - exacto(b) || a.nombre.localeCompare(b.nombre, 'es'));

return [{
  json: {
    dato,
    total: clientes.length,
    requiere_eleccion: clientes.length > 1,
    hay_mas: clientes.length > LIMITE,
    resultados: clientes.slice(0, LIMITE),
  },
}];

