//
// Un surtido es la lista cerrada de lo que se puede vender al cliente. Cada línea es
// {codigoMarca, descripcionMarca, codigoGrupo, descripcionGrupo, codigoArticulo, descripcion,
// fechaDesde, fechaFin} (fechaFin 31/12/2500 = sin fin; las descripciones faltan si el código
// va vacío). Según lo que venga relleno (09/11/2026):
//   - codigoArticulo numérico → artículo (marca y grupo son los del artículo, informativos);
//   - sin artículo, con marca y sin grupo → TODA la marca ("marcas");
//   - sin artículo, con marca y grupo → todo ese grupo de la marca ("grupos");
//   - código no numérico (SOLOENDOSO, FINDESERVI, CSACLIENTE...) → marca del ERP ("avisos").
// La API NO expande marcas ni grupos en artículos.
//
// Cada línea es además de un cliente factura (clienteFactura, 11/11/2026): el subdistribuidor que hace el endoso
// (p. ej. Vicky Foods 4400000173). 0000000001 = genérico: vale sea quien sea el que factura (nombres en comun.js,
// NOMBRES_CF). Con la entrada cliente_factura solo se devuelven las líneas de ese cliente factura.
const LIMITE = 60;
const e = $('Consulta').first().json;
const tb = $('Tabla').first().json;

if (tb.error) return fallo(tb.error);
const { datos: lista, error } = leerApi($input.first().json, 'surtidos', true);
if (error) return fallo(error);

const hoy = hoyIso();
const { palabras, aciertos } = buscador(e.articulo);
const esArticulo = (c) => /^\d+$/.test(c);

const todas = lista.map((p) => {
  const hasta = t(p.fechaFin);
  const l = {
    codigo_cf: t(p.clienteFactura),
    articulo: t(p.codigoArticulo),
    descripcion: sp(p.descripcion),
    codigo_marca: t(p.codigoMarca),
    marca: sp(p.descripcionMarca) || t(p.codigoMarca),
    codigo_grupo: t(p.codigoGrupo),
    grupo: sp(p.descripcionGrupo) || t(p.codigoGrupo),
    desde: t(p.fechaDesde),
    hasta: hasta && !hasta.endsWith('/2500') ? hasta : '',
  };
  l.cliente_factura = nombreCf(l.codigo_cf);
  l.vigente = (!l.desde || iso(l.desde) <= hoy) && (!hasta || hoy <= iso(hasta));
  return l;
});
const cfFiltro = t(e.cliente_factura);
const lineas = cfFiltro ? todas.filter((l) => l.codigo_cf === cfFiltro) : todas;
const fechas = (l) => ({ cliente_factura: l.cliente_factura, desde: l.desde, hasta: l.hasta, vigente: l.vigente });
// Los avisos (SOLOENDOSO...) son de la tabla: se miran en todas las líneas.
const avisos = todas.filter((l) => l.articulo && !esArticulo(l.articulo)).map((l) => `${l.articulo}: ${l.descripcion}`);
// Marcas completas y grupos de marca: son pocas líneas y van siempre, sin filtrar, para que el agente
// pueda decir si un artículo que no aparece suelto entra por su marca o su grupo.
const sinArticulo = lineas.filter((l) => !l.articulo && l.codigo_marca);
const marcas = sinArticulo.filter((l) => !l.codigo_grupo)
  .map((l) => ({ codigo_marca: l.codigo_marca, marca: l.marca, ...fechas(l) }));
const grupos = sinArticulo.filter((l) => l.codigo_grupo)
  .map((l) => ({ codigo_marca: l.codigo_marca, marca: l.marca, codigo_grupo: l.codigo_grupo, grupo: l.grupo, ...fechas(l) }));
const articulos = lineas.filter((l) => esArticulo(l.articulo)).map((l) => ({
  articulo: l.articulo, descripcion: l.descripcion, marca: l.marca, grupo: l.grupo, ...fechas(l),
}));
// Primero los clientes factura concretos y al final el genérico.
const ordenCf = (n) => (n === 'Genérico' ? 'ZZZ' : n);
// El filtro busca en código, descripción, marca y grupo ("dulcesol" encuentra los artículos DSOL de la marca).
const texto = (l) => `${l.articulo} ${l.descripcion} ${l.marca} ${l.grupo}`;
const productos = articulos
  .filter((l) => aciertos(texto(l)) === palabras.length)
  .sort((a, b) => ordenCf(a.cliente_factura).localeCompare(ordenCf(b.cliente_factura), 'es')
    || a.marca.localeCompare(b.marca, 'es') || a.descripcion.localeCompare(b.descripcion, 'es')
    || iso(a.desde).localeCompare(iso(b.desde)));
// Resumen por cliente factura: código, nombre, nº de marcas completas, de grupos y de artículos, y artículos
// por marca (para surtidos grandes: el agente solo recibe LIMITE artículos).
const resumen = {};
lineas.filter((l) => l.codigo_marca || esArticulo(l.articulo)).forEach((l) => {
  const r = resumen[l.codigo_cf] ||= { codigo: l.codigo_cf, nombre: l.cliente_factura, marcas: 0, grupos: 0, articulos: 0, articulos_por_marca: {} };
  if (esArticulo(l.articulo)) {
    r.articulos += 1;
    const m = l.marca || 'SIN MARCA';
    r.articulos_por_marca[m] = (r.articulos_por_marca[m] || 0) + 1;
  } else if (!l.articulo) {
    r[l.codigo_grupo ? 'grupos' : 'marcas'] += 1;
  }
});
const clientesFactura = Object.values(resumen).sort((a, b) => ordenCf(a.nombre).localeCompare(ordenCf(b.nombre), 'es'));

// Si con todas las palabras no sale nada, los que tienen más palabras en común (como mucho 10),
// para que el agente no conteste "no está" solo porque la descripción lo escribe distinto.
function parecidos(todos, hallados) {
  if (hallados.length || palabras.length < 2) return [];
  return todos.map((l) => [aciertos(texto(l)), l]).filter(([n]) => n > 0)
    .sort((a, b) => b[0] - a[0]).slice(0, 10).map(([, l]) => l);
}

return [{
  json: {
    tipo: 'surtido',
    codigo_cliente: t(e.codigo_cliente),
    tabla: tb.tabla,
    articulo: t(e.articulo),
    cliente_factura: cfFiltro ? { codigo: cfFiltro, nombre: nombreCf(cfFiltro), lineas_de_otros: todas.length - lineas.length } : null,
    avisos: [...new Set(avisos)],
    clientes_factura: clientesFactura,
    marcas,
    grupos,
    total_tabla: articulos.length,
    total: productos.length,
    hay_mas: productos.length > LIMITE,
    productos: productos.slice(0, LIMITE),
    parecidos: parecidos(articulos, productos),
  },
}];

// Funciones comunes de los nodos Code del flujo chat-ia-clientes-ayc.json. build_workflow.py pone este fichero
// delante del código de cada nodo, así que lo que se define aquí no se puede volver a declarar en los otros .js.
const t = (v) => String(v ?? '').trim();
// Quita los espacios de relleno de las descripciones del ERP.
const sp = (v) => t(v).replace(/\s{2,}/g, ' ');
// dd/mm/aaaa → aaaa-mm-dd, para comparar fechas como texto.
const iso = (f) => t(f).split('/').reverse().join('-');
const hoyIso = () => $now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd');
const fallo = (mensaje) => [{ json: { error: mensaje } }];

// Acciones de las herramientas de tablas: base de la URL de la API (/api/<base>/...), nombre para los mensajes y
// campo del valor (null en surtidos).
const TIPOS = {
  preciosEspeciales: { base: 'preciosEspeciales', que: 'precios especiales', campo: 'precio' },
  descuentos: { base: 'descuentos', que: 'descuentos', campo: 'descuento' },
  surtidos: { base: 'surtidos', que: 'surtido', campo: null },
};
TIPOS.actualizarPreciosEspeciales = TIPOS.preciosEspeciales;
TIPOS.actualizarDescuentos = TIPOS.descuentos;
TIPOS.actualizarSurtidos = TIPOS.surtidos;

// Cliente factura de las líneas de surtido. La API no da el nombre: los conocidos van aquí; el resto, por su código.
const GENERICO = '0000000001';
const NOMBRES_CF = { [GENERICO]: 'Genérico', '4400000173': 'VICKY FOODS PRODUCTS SLU' };
const nombreCf = (c) => NOMBRES_CF[c] || (c ? `Cliente factura ${c}` : 'Sin cliente factura');

// Mensaje de la API dentro de un error de n8n: '404 - {"mensaje":"No hay datos comerciales (CLP) ..."}'.
const mensajeApi = (err) => (String(err?.message || '').match(/"(?:mensaje|message)"\s*:\s*"([^"]*)"/) || [])[1];

// Lee la salida de un nodo HTTP de la API ({ data } en texto, o { error } si no ha respondido).
// Devuelve { datos } o { error } con un mensaje para el usuario. lista = true: se espera un array.
function leerApi(r, que, lista = false) {
  if (r.error) {
    return { error: mensajeApi(r.error) || `La API de ${que} no responde o ha dado un error. Prueba de nuevo en unos segundos.` };
  }
  let d;
  try {
    d = JSON.parse(r.data);
  } catch (err) {
    return { error: `La API de ${que} ha devuelto una respuesta no válida.` };
  }
  if (lista && !Array.isArray(d)) return { error: d?.mensaje || `La API de ${que} ha dado un error.` };
  return { datos: d };
}

// Búsqueda por palabras en las descripciones, sin tildes ni mayúsculas y sin palabras vacías
// ("poker de vainilla" → POKER, VAINILLA). aciertos(texto) = cuántas palabras de la búsqueda contiene el texto.
const plano = (s) => t(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase();
const VACIAS = new Set(['DE', 'DEL', 'LA', 'EL', 'LOS', 'LAS', 'CON', 'Y', 'EN', 'AL', 'A', 'UN', 'UNA', 'PARA', 'POR']);
function buscador(busqueda) {
  const palabras = plano(busqueda).split(/[\s,.;]+/).filter((w) => w && !VACIAS.has(w));
  return { palabras, aciertos: (texto) => { const p = plano(texto); return palabras.filter((w) => p.includes(w)).length; } };
}

// Conversión de números escritos por el usuario (formato español) al número que espera la API de AYC
// (JSON con punto decimal). Se copia dentro de los nodos Code que preparan precios o descuentos para
// .../actualizar (build_workflow.py). La API no acepta texto: "1,25" entre comillas lo guardaría como 125.
//
//   aNumero('1,25')      → { valor: 1.25 }
//   aNumero('1.250,5 €') → { valor: 1250.5 }
//   aNumero('6,5 %')     → { valor: 6.5 }
//   aNumero('1.25')      → { valor: 1.25 }      (punto decimal, por si lo escriben así)
//   aNumero('1.250')     → { error: '...' }     (¿mil doscientos cincuenta o uno con veinticinco? se pregunta)
//   aNumero(1.25)        → { valor: 1.25 }      (si ya es número, se deja)
function aNumero(entrada) {
  if (typeof entrada === 'number') {
    return Number.isFinite(entrada) ? { valor: entrada } : { error: `"${entrada}" no es un número.` };
  }
  const original = String(entrada ?? '').trim();
  const s = original.replace(/[\s €%]/g, '').replace(/^\+/, '');
  if (!s) return { error: 'Falta el número.' };
  if (!/^-?[\d.,]+$/.test(s) || !/\d/.test(s)) return { error: `"${original}" no es un número.` };

  const comas = (s.match(/,/g) || []).length;
  const puntos = (s.match(/\./g) || []).length;
  let normal;
  if (comas && puntos) {
    // Los dos: el último que aparece es el decimal y el otro separa miles (grupos de 3 cifras).
    const dec = s.lastIndexOf(',') > s.lastIndexOf('.') ? ',' : '.';
    const miles = dec === ',' ? '.' : ',';
    const [entera, decimales, ...resto] = s.split(dec);
    if (resto.length || decimales.includes(miles) || !/^-?\d{1,3}([.,]\d{3})*$/.test(entera)) {
      return { error: `"${original}" no es un número válido.` };
    }
    normal = `${entera.split(miles).join('')}.${decimales}`;
  } else if (comas) {
    // Solo comas: una es el decimal (formato español). Varias = separador de miles ("1,250,000"): no se adivina.
    if (comas > 1) return { error: `"${original}" no es un número válido. Escribe los decimales con coma (p. ej. 1,25).` };
    normal = s.replace(',', '.');
  } else if (puntos) {
    if (puntos > 1) {
      // "1.250.000": puntos de miles.
      if (!/^-?\d{1,3}(\.\d{3})+$/.test(s)) return { error: `"${original}" no es un número válido.` };
      normal = s.split('.').join('');
    } else if (/^-?\d{1,3}\.\d{3}$/.test(s)) {
      // Un punto y 3 cifras detrás: en español es separador de miles, pero puede ser un decimal mal escrito.
      return { error: `"${original}" es ambiguo: ¿${s.replace('.', '')} o ${s.replace('.', ',')}? Escribe los decimales con coma.` };
    } else {
      normal = s; // punto decimal ("1.25", "6.5")
    }
  } else {
    normal = s;
  }

  normal = normal.replace(/^(-?)\./, '$10.'); // ",5" → 0.5
  const valor = Number(normal);
  return Number.isFinite(valor) && /^-?\d+(\.\d+)?$/.test(normal)
    ? { valor }
    : { error: `"${original}" no es un número válido.` };
}


// Código del nodo "Preparar actualización" del flujo chat-ia-clientes-ayc.json (build_workflow.py lo copia en el JSON,
// precedido de comun.js y numero_es.js). Valida lo que pide el agente para dar de alta o modificar una línea de precios
// especiales, descuentos o surtido. La tabla la decide antes el nodo Tabla (la que da el usuario o la del cliente).
// Devuelve { base, campo, tabla, producto, valor, fecha_desde, fecha_fin, cliente_factura, ... } o { error }.
const e = $('Consulta').first().json;
const tipo = TIPOS[e.accion];
const tb = $('Tabla').first().json;
if (tb.error) return fallo(tb.error);
const tabla = tb.tabla;
if (!/^\d+$/.test(tabla.codigo) || Number(tabla.codigo) <= 0) return fallo(`Número de tabla no válido: ${tabla.codigo}.`);
// 999 y 998 son "sin precios especiales / descuentos / surtido" y las comparten decenas de miles de clientes.
if (['998', '999'].includes(String(Number(tabla.codigo)))) {
  return fallo(`La tabla ${Number(tabla.codigo)} es la de los clientes sin ${tipo.que} y la comparten miles de clientes: `
    + 'no se modifica. Si el cliente necesita condiciones propias, hay que asignarle otra tabla en el ERP.');
}

// Producto: artículo, o marca completa, o grupo (de una marca).
const producto = {
  codigoArticulo: t(e.articulo).toUpperCase(),
  codigoMarca: t(e.codigo_marca).toUpperCase(),
  codigoGrupo: t(e.codigo_grupo).toUpperCase(),
};
if (!producto.codigoArticulo && !producto.codigoMarca && !producto.codigoGrupo) {
  return fallo('Falta el código del artículo (o la marca o el grupo, si la línea es de marca completa o de grupo).');
}
if (producto.codigoArticulo && !/^[A-Z0-9]{1,10}$/.test(producto.codigoArticulo)) {
  return fallo(`"${e.articulo}" no es un código de artículo. Busca antes el artículo para saber su código (p. ej. 14403).`);
}
if (producto.codigoArticulo) {
  producto.codigoMarca = '';
  producto.codigoGrupo = '';
}
if (producto.codigoMarca.length > 6 || producto.codigoGrupo.length > 6) return fallo('Los códigos de marca y de grupo tienen como mucho 6 caracteres.');

// Valor: obligatorio en precios y descuentos (la API guardaría 0 si faltara). aNumero viene de numero_es.js.
let valor = null;
if (tipo.campo) {
  const nombre = tipo.campo === 'precio' ? 'Precio' : 'Descuento';
  if (!t(e.valor)) return fallo(`Falta el ${tipo.campo} nuevo.`);
  const n = aNumero(e.valor);
  if (n.error) return fallo(`${nombre}: ${n.error}`);
  valor = n.valor;
  if (tipo.campo === 'precio' && valor < 0) return fallo('El precio no puede ser negativo.');
  if (tipo.campo === 'descuento' && (valor < 0 || valor > 100)) return fallo('El descuento tiene que estar entre 0 y 100 %.');
}

// Fechas dd/mm/aaaa (vacías = por defecto: alta desde hoy y sin fin; modificación, las que tenga).
function fecha(v, nombre) {
  const s = t(v);
  if (!s) return { valor: '' };
  const m = s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);
  const d = m && new Date(Date.UTC(+m[3], +m[2] - 1, +m[1]));
  if (!m || d.getUTCDate() !== +m[1] || d.getUTCMonth() !== +m[2] - 1) return { error: `${nombre} no válida (${s}). Usa dd/mm/aaaa.` };
  return { valor: `${m[1].padStart(2, '0')}/${m[2].padStart(2, '0')}/${m[3]}` };
}
const desde = fecha(e.fecha_desde, 'Fecha desde');
const hasta = fecha(e.fecha_fin, 'Fecha fin');
if (desde.error || hasta.error) return fallo(desde.error || hasta.error);
if (desde.valor && hasta.valor && iso(hasta.valor) < iso(desde.valor)) return fallo('La fecha fin no puede ser anterior a la fecha desde.');

const clienteFactura = tipo.base === 'surtidos' ? t(e.cliente_factura) : '';
if (clienteFactura && !/^\d{10}$/.test(clienteFactura)) return fallo(`Cliente factura no válido: ${clienteFactura} (son 10 cifras, p. ej. 4400000173).`);

return [{
  json: {
    accion: e.accion,
    base: tipo.base,
    que: tipo.que,
    campo: tipo.campo,
    codigo_cliente: t(e.codigo_cliente),
    tabla,
    producto,
    valor,
    fecha_desde: desde.valor,
    fecha_fin: hasta.valor,
    cliente_factura: clienteFactura,
    confirmacion: t(e.confirmacion),
  },
}];

